"""Compose both complete research iterations without overwriting their source reports."""
from pathlib import Path
import re,json,shutil
R=Path(__file__).resolve().parents[1]; C=R/'cycles/fewshot'
original=(R/'cycles/iteration1-report.html').read_text();new=(C/'report.html').read_text()
base='/projects/age-prediction/'
caption=(R/'figures/design-review/caption.txt').read_text().strip()
fig=f'<figure class="fig"><a href="{base}figures/design-review/iteration1_integration.svg"><img src="{base}figures/design-review/iteration1_integration.svg" alt="Iteration 1: microbiome integration performance, repeat consistency and study heterogeneity" loading="lazy"></a><figcaption><strong>Iteration 1 / Integration analysis.</strong> {caption} <a href="{base}figures/design-review/iteration1_integration.pdf">PDF</a> / <a href="{base}figures/design-review/iteration1_integration.svg">SVG</a> / <a href="{base}figures/fig4_metadata_microbiome_integration.pdf">Original figure</a></figcaption></figure>'
original,n=re.subn(r'<figure class="fig">(?:(?!</figure>).)*fig4_metadata_microbiome_integration(?:(?!</figure>).)*</figure>',lambda m:fig,original,flags=re.S)
assert n==1,n
# Use editable vector assets at every display width.
for name in ['original','new']:
 val=locals()[name];val=re.sub(r'(<img src="[^"]+)\.png"',r'\1.svg"',val);locals()[name]=val
css='''.age-study .iteration-heading{font-family:Helvetica,Arial,sans-serif;font-size:25px;line-height:1.3;letter-spacing:-.02em;margin:64px 0 20px;padding-top:24px;border-top:2px solid #272727;scroll-margin-top:30px}.age-study .iteration-heading small{display:block;font-family:ui-monospace,monospace;font-size:12px;letter-spacing:.08em;color:#666;margin-bottom:12px;text-transform:uppercase}.age-study .iteration-nav{display:flex;gap:12px;flex-wrap:wrap;padding:18px 0;border-block:1px solid #d2d2ca;margin-bottom:30px;font-size:13px}.age-study figure{width:min(960px,calc(100vw - 70px));max-width:none;margin:30px 0!important;padding:14px!important;box-sizing:border-box;background:white}.age-study figure img{width:100%;height:auto;display:block}.age-study figcaption{max-width:850px;font-size:12px;line-height:1.6;margin-top:14px}.age-study h3::before,.age-study h4::before{content:none!important}.age-study .age-project>h3:first-child{margin-top:20px}.age-study .table-scroll{overflow-x:auto}@media(max-width:720px){.age-study figure{width:100%;padding:7px!important}.age-study .iteration-heading{font-size:22px}}'''
def clean_article(fragment):
    fragment=re.sub(r'<h3>Code and data availability</h3>.*?(?=<h3>|</div>\s*$)', '', fragment, flags=re.S|re.I)
    fragment=re.sub(r'<li>Roh et al\. Integration of Blood Methylome.*?</li>', '', fragment, flags=re.S)
    fragment=re.sub(r'<a\b[^>]*>\s*(?:PDF|SVG|Original figure)\s*</a>', '', fragment, flags=re.I)
    fragment=re.sub(r'<a\b[^>]*>(<img\b[^>]*>)</a>', r'\1', fragment)
    fragment=fragment.replace('\u00b7','/').replace('•','/')
    fragment=re.sub(r'(?:\s*/\s*)+(?=</figcaption>)','',fragment)
    fragment=re.sub(r'<h[234][^>]*>\s*(?:#|\.|\s)*</h[234]>','',fragment)
    return fragment

def formalize_iteration1(fragment):
    replacements = [
        (r'<h4>Paired methylation-clock and gut microbiome pilot</h4><p>.*?</p>',
         '<h4>Early integration degrades prediction in a paired methylation-clock and gut-microbiome cohort</h4><p>The paired analysis used the HI-SEED <a href="https://doi.org/10.6084/m9.figshare.26487670">release</a>, comprising 123 participants with concordant identifiers across metadata and microbial abundance tables. Across three repeated five-fold validations, calibrated Horvath scores achieved an MAE of 4.87 years, genus-level microbial profiles achieved 12.59 years and early feature integration achieved 9.53 years. Relative to calibrated methylation scores, integration increased MAE by 4.66 years (95% conditional interval, 3.35–6.03). The analysis uses a pretrained methylation-clock score rather than raw methylation measurements and has not been externally validated.</p>'),
        (r'<h4>Clock-preserving residual fusion limits loss of predictive accuracy</h4><p>.*?</p><p>.*?</p>',
         '<h4>Clock-preserving residual integration recovers unimodal predictive accuracy</h4><p>A subsequent formulation retained an unpenalized clock-calibration term and estimated an independent correction from clock-orthogonalized microbial features. Across identical outer partitions, residual integration achieved an MAE of 4.848 years, compared with 4.851 years for inner-selected clock calibration and 4.870 years for ordinary least-squares calibration. Relative to early feature integration (MAE, 9.529 years), the post hoc paired reduction was 4.68 years (95% conditional interval, 3.42–6.07), equivalent to a 49.1% reduction.</p><p>The prespecified contrast with selected clock calibration was 0.004 years (95% conditional interval, −0.061 to 0.070). Although a microbial correction was selected in 12 of 15 outer training partitions, it did not produce a measurable held-out improvement. Residual integration therefore preserved the predictive accuracy of the methylation component but did not establish independent microbial complementarity.</p>'),
        (r'<h4>Exploratory pathway analysis</h4><p>.*?</p>',
         '<h4>Probe-aware pathway analysis identifies no FDR-significant enrichment</h4><p>The 500 selected methylation probes mapped to 472 unique genes. Reactome analysis tested 1,333 pathways against a background of 14,475 genes represented on the measured array. No pathway passed Benjamini–Hochberg correction at FDR &lt; 0.05. The nominally ranked pathways in Figure 3 are therefore presented as descriptive annotations rather than pathway-level evidence of biological ageing. Complete results are provided in the <a href="/projects/age-prediction/results/reactome_probe_aware_enrichment.csv">enrichment table</a>.</p>'),
        (r'<h3>Discussion</h3>.*?(?=<p>For component errors)',
         '<h3>Discussion</h3><p>Skin microbial features contributed predictive information beyond study, body site and sex in repeated participant-held-out validation. The aggregate improvement was reproducible across three partition seeds but heterogeneous across source studies, with the largest cohort accounting for most of the observed reduction. The result therefore supports conditional predictive value within the sampled study mixture rather than study-independent transportability.</p><p>The paired HI-SEED analysis further showed that multimodal performance depends on model formulation. Direct concatenation degraded a calibrated methylation predictor, whereas residual integration preserved its accuracy by restricting microbial features to a correction term. The absence of improvement over clock calibration indicates that model architecture alone cannot establish complementary biological information.</p>'),
        (r'<p>The unpaired cohorts do not identify.*?</p>\s*<p>Additional limitations.*?</p>',
         '<p>The unpaired blood and skin cohorts do not identify the within-person covariance or joint bias terms. Consequently, their component errors cannot be used to infer empirical blood–skin fusion performance. Evaluation of this model class requires paired specimens, prespecified weight estimation in training or calibration data and comparison with both unimodal components in an untouched test cohort.</p><p>Additional limitations include dependence on processed public matrices, ambiguous identifiers in one excluded microbiome study, restricted age coverage in the external methylation cohort and unresolved assay and study effects. The outcome is chronological age; no inference concerning biological age or clinical utility is supported.</p>'),
    ]
    for pattern, replacement in replacements:
        fragment, count = re.subn(pattern, replacement, fragment, count=1, flags=re.S)
        assert count == 1, pattern
    return fragment

def editorial_revision(fragment):
    replacements = {
        '<p><strong>Principal empirical finding.</strong> Integration of skin microbial features with study, body-site, and sex information reduced participant-weighted age-prediction error from 9.71 to 8.74 years (10.0% reduction). The paired improvement was 0.97 years (95% conditional bootstrap interval, 0.66–1.28), with a positive average difference in each of three repeated nested-validation runs. This result concerns microbiome–metadata integration in the skin cohort; it is not an estimate of blood–skin fusion accuracy.</p>':
        '<p>Age-associated variation in the skin microbiome remained predictive after accounting for study, body site and sex, with joint modelling reducing participant-weighted mean absolute error from 9.71 to 8.74 years across three repeated nested validations. The corresponding reduction of 0.97 years had a 95% conditional bootstrap interval of 0.66 to 1.28 years and was observed in every validation repetition, although the magnitude of improvement differed among the source studies.</p>',
        '<p>Both improvements were positive in all three repetitions. Source-study effects were heterogeneous: the reduction versus metadata was 1.53 years in study 10317, −0.46 years in study 1841, and 0.19 years in study 2010. The aggregate benefit was therefore driven primarily by study 10317, which contributed 237 of 339 participant identifiers; it was not a uniform improvement across studies.</p>':
        '<p>Although the pooled improvement was recovered in each validation repetition, estimates within individual studies ranged from a 1.53-year reduction in study 10317 to a 0.46-year increase in study 1841, with study 2010 showing a 0.19-year reduction. Study 10317 contributed 237 of the 339 participant identifiers and accounted for most of the aggregate effect, indicating that the predictive contribution of microbial features varied with cohort composition.</p>',
        '<p>Blood methylation prediction achieved R² = 0.91 during plate-held-out validation. External validation in control women aged 52–78 years yielded MAE = 6.03 years and R² = -1.38. Negative external R² indicates higher squared error than prediction by the external-cohort mean. The difference between internal and external results therefore limits evidence for generalization despite improvement over the discovery-training median baseline.</p>':
        '<p>Plate-held-out validation of the blood methylation model yielded an R² of 0.91, whereas evaluation in an external cohort of control women aged 52 to 78 years yielded a mean absolute error of 6.03 years and an R² of -1.38. The decline in external performance, including a squared error greater than that obtained from the external cohort mean, indicates substantial sensitivity to differences between the discovery and validation populations.</p>',
        '<p>The skin microbiome model yielded MAE = 9.17 years, compared with 10.06 years for the study/site/sex model. The paired participant-bootstrap reduction was 0.89 years (95% conditional interval, 0.46–1.32). Microbial composition contributed predictive information in this validation setting, although metadata accounted for a substantial fraction of the observed signal.</p>':
        '<p>Participant-held-out prediction from skin microbial composition yielded a mean absolute error of 9.17 years, compared with 10.06 years for a model containing study, body site and sex, which corresponded to a paired reduction of 0.89 years with a 95% conditional interval of 0.46 to 1.32 years. Microbial composition therefore captured age-associated variation beyond the recorded cohort variables, while the performance of the metadata model showed that study design and sampling site explained a substantial proportion of the predictive signal.</p>',
        '<p>Random sample splitting placed participants represented in the training set in 90.5% of test samples. Participant and study holdout eliminated this overlap. For the fixed forest, participant-weighted MAE increased from 8.93 years under random splitting to 9.24 years under participant holdout. The paired difference was 0.31 years (95% conditional interval, 0.15–0.48). For identical participant-held-out predictions, sample-weighted MAE was 6.44 years, demonstrating sensitivity to the evaluation weights.</p>':
        '<p>Random sample partitioning placed observations from previously encountered participants in 90.5% of the test samples, whereas participant-level and study-level partitioning removed this overlap. Under participant holdout, the participant-weighted mean absolute error increased from 8.93 to 9.24 years, with a paired increase of 0.31 years and a 95% conditional interval of 0.15 to 0.48 years, while sample weighting reduced the apparent error for the same predictions to 6.44 years and demonstrated the influence of repeated sampling on performance estimates.</p>',
        '<p>Leave-one-study-out MAE was 18.35 years. Study 1841 predominantly included younger adults, whereas study 10317 covered a broader and older population. Differences in age distribution and study composition are therefore plausible contributors to the reduced transfer performance. These analyses use different eligibility criteria, weighting, transformations, and model settings from the source publication and do not constitute a direct reproduction of its reported accuracy.</p>':
        '<p>Generalization across studies was markedly weaker than performance within participant-held-out partitions, with leave-one-study-out validation yielding a mean absolute error of 18.35 years. Study 1841 consisted predominantly of younger adults, whereas study 10317 spanned a broader and older population, suggesting that differences in age distribution and study-specific measurement structure contributed to the loss of predictive accuracy.</p>',
        '<p>Two external blood samples had more than 1% missing CpG measurements. The most incomplete sample had approximately 57% missing measurements and a predicted age of −28.4 years at recorded age 74. Both samples were retained in the primary analysis. An exploratory 1% missingness filter applied to the existing predictions retained 272 controls and yielded MAE = 5.48 years and R² = −0.26. This post hoc sensitivity analysis identifies a quality-control concern without establishing external validity.</p>':
        '<p>Two samples in the external blood cohort exceeded 1% missing CpG measurements, including one sample with approximately 57% missingness whose predicted age was -28.4 years at a recorded age of 74 years. Applying a 1% missingness threshold to the recorded predictions retained 272 controls and changed the mean absolute error to 5.48 years and the R² to -0.26, indicating that assay completeness contributed materially to the external error distribution.</p>',
        '<p>CpGs annotated to NHLRC1, SCGN, and ASPA had large standardized ridge coefficients and were selected in all five outer training sets. These conditional coefficients do not identify causal aging mechanisms. Microbial training-importance ranks included ASVs assigned to Mycoplasma and Enterobacteriaceae; interpretation is limited by feature correlation, potential study effects, and the resolution of the released taxonomic annotations.</p>':
        '<p>CpGs annotated to NHLRC1, SCGN and ASPA were selected in all five outer training sets and carried among the largest standardized coefficients in the methylation model, while the highest microbial importance ranks included amplicon sequence variants assigned to Mycoplasma and Enterobacteriaceae. These model-derived rankings identify reproducible predictive features whose biological interpretation remains dependent on correlated measurements, study effects and the taxonomic resolution of the released data.</p>',
        '<p>Matched unshuffled models had lower MAE than the ten corresponding label-permutation runs in each modality. This diagnostic supports learnable age-associated structure in the selected datasets, but the number of permutations is insufficient for a precise significance estimate.</p>':
        '<p>Across both molecular modalities, models fitted to the observed age labels produced lower mean absolute error than each of ten matched label-permutation runs, providing evidence that the selected feature matrices contained learnable age-associated structure while leaving the magnitude of permutation-based significance imprecisely estimated.</p>',
        '<p>The 500 selected methylation probes mapped to 472 unique genes. Reactome analysis tested 1,333 pathways against a background of 14,475 genes represented on the measured array. No pathway passed Benjamini–Hochberg correction at FDR &lt; 0.05. The nominally ranked pathways in Figure 3 are therefore presented as descriptive annotations rather than pathway-level evidence of biological ageing. Complete results are provided in the <a href="/projects/age-prediction/results/reactome_probe_aware_enrichment.csv">enrichment table</a>.</p>':
        '<p>The 500 methylation probes selected by the final model mapped to 472 unique genes, which were evaluated across 1,333 Reactome pathways using the 14,475 genes represented on the array as the measured background. None of the tested pathways passed Benjamini-Hochberg correction at a false discovery rate below 0.05, and the nominally ranked pathways shown in Figure 3 are consequently interpreted as hypotheses for biological investigation rather than evidence of pathway-level enrichment.</p>',
        '<p>Skin microbial features contributed predictive information beyond study, body site and sex in repeated participant-held-out validation. The aggregate improvement was reproducible across three partition seeds but heterogeneous across source studies, with the largest cohort accounting for most of the observed reduction. The result therefore supports conditional predictive value within the sampled study mixture rather than study-independent transportability.</p>':
        '<p>Repeated participant-held-out validation showed that skin microbial features improved chronological age prediction beyond study, body site and sex, with a consistent pooled reduction in error across three partition seeds. The concentration of this improvement in the largest source study, together with the marked deterioration under study-level holdout, indicates that the microbial signal included both age-associated information shared across participants and structure specific to the contributing cohorts.</p>',
        '<p>The paired HI-SEED analysis further showed that multimodal performance depends on model formulation. Direct concatenation degraded a calibrated methylation predictor, whereas residual integration preserved its accuracy by restricting microbial features to a correction term. The absence of improvement over clock calibration indicates that model architecture alone cannot establish complementary biological information.</p>':
        '<p>Analysis of the paired HI-SEED cohort showed that the effect of multimodal integration depended strongly on the statistical formulation, because direct concatenation of methylation-clock scores and microbial abundances degraded prediction whereas residual integration preserved the accuracy of the calibrated methylation score. The microbial correction did not improve performance beyond calibration alone, suggesting that the available genus-level measurements did not provide stable complementary information after the methylation-derived age estimate had been modelled.</p>',
        '<p>The unpaired blood and skin cohorts do not identify the within-person covariance or joint bias terms. Consequently, their component errors cannot be used to infer empirical blood–skin fusion performance. Evaluation of this model class requires paired specimens, prespecified weight estimation in training or calibration data and comparison with both unimodal components in an untouched test cohort.</p>':
        '<p>Because the blood methylation and skin microbiome measurements were obtained from different individuals, the covariance and joint bias of the two component errors could not be estimated from these cohorts. A definitive evaluation of blood and skin integration will require paired specimens collected from the same participants, estimation of fusion parameters within training or calibration data and comparison with both unimodal predictors in an independent test cohort.</p>',
        '<p>Additional limitations include dependence on processed public matrices, ambiguous identifiers in one excluded microbiome study, restricted age coverage in the external methylation cohort and unresolved assay and study effects. The outcome is chronological age; no inference concerning biological age or clinical utility is supported.</p>':
        '<p>The interpretation of these findings is further constrained by reliance on processed public matrices, ambiguous participant identifiers in one excluded microbiome study, restricted age coverage in the external methylation cohort and residual assay and study effects. Chronological age was the sole prediction target, and associations with physiological ageing, disease susceptibility or clinical outcomes remain to be determined in appropriately designed cohorts.</p>',
        '<p>This analysis examines adaptation of DNA-methylation age predictors under restricted target-cohort supervision. It extends the preceding multimodal study by evaluating representation learning and support-set model selection across independent blood-derived methylation cohorts.</p>':
        '<p>To determine whether epigenetic age predictors can be adapted when few labelled samples are available from a new cohort, we evaluated episodic representation learning and support-conditioned regression across two independent blood-derived methylation datasets.</p>',
        '<p>At the prespecified 16-label endpoint, the neural adapter reduced MAE by 4.3% in whole blood and 9.5% in PBMCs relative to the comparator selected by cross-validation within each support set. Both paired contrasts remained significant after Holm correction across cohorts. Inference is conditional on the recorded support draws and fixed query populations and therefore does not quantify uncertainty across independently sampled cohorts or subsequent model-development decisions.</p>':
        '<p>At the prespecified 16-label endpoint, neural adaptation reduced mean absolute error by 4.3% in whole blood and 9.5% in peripheral blood mononuclear cells relative to the classical comparator selected within each support set, with both paired contrasts remaining significant after Holm correction across cohorts. The effects were estimated across the recorded support draws and external query participants, establishing a consistent advantage over data-limited model selection within these two target cohorts.</p>',
        '<p>The whole-blood advantage was largest at eight labels and decreased with additional target-domain supervision. In PBMCs, neural predictions remained close to affine recalibration across label budgets. The full 16-label comparison is reported below to distinguish the prespecified support-selected contrast from comparisons with individual estimators.</p>':
        '<p>The improvement in whole blood was greatest with eight labelled participants and diminished as the support set increased, whereas predictions in peripheral blood mononuclear cells remained close to affine recalibration across label budgets. Comparison of all estimators at 16 labels showed that the neural model primarily improved the reliability of adaptation selected from very small support sets rather than uniformly surpassing every fixed estimator.</p>',
        '<p>In whole blood, frozen source ridge achieved an MAE of 6.842 years, compared with 7.293 years for the augmented neural model; linear and radial-basis-function residual kernels yielded MAEs of 7.038 and 7.052 years, respectively. In PBMCs, affine recalibration achieved an MAE of 3.854 years. The neural improvement relative to affine recalibration was 0.185 years, with a conditional interval that included zero. Thus, the primary result is specific to support-set model selection rather than uniform superiority over each classical estimator. The discrepancy further indicates that cross-validation among candidate adapters is unstable when only 16 target labels are available.</p>':
        '<p>In whole blood, the frozen source ridge model achieved a mean absolute error of 6.842 years, compared with 7.293 years for the augmented neural model and 7.038 and 7.052 years for linear and radial basis function residual kernels. In peripheral blood mononuclear cells, affine recalibration achieved an error of 3.854 years, and its 0.185-year difference from the neural adapter had a conditional interval that included zero, indicating that the significant primary contrasts arose from improved performance relative to support-selected comparators rather than superiority over every individual estimator.</p>',
        '<p>Removal of synthetic feature augmentation produced MAEs of 7.266 years in whole blood and 3.656 years in PBMCs, marginally below the corresponding augmented estimates. No predictive benefit from the evaluated augmentation distribution was observed. Source-validation trajectories also varied across checkpoints, supporting checkpoint selection on data isolated from episodic training.</p>':
        '<p>Removing synthetic feature augmentation yielded mean absolute errors of 7.266 years in whole blood and 3.656 years in peripheral blood mononuclear cells, which were marginally lower than the corresponding augmented estimates. The evaluated perturbation distribution therefore did not improve prediction, while variation in source-validation performance across training checkpoints supported the use of data independent from episodic optimization for checkpoint selection.</p>',
        '<p>A post hoc assay-matching analysis refitted the source ridge model using only probes represented in each target dataset. Regularization was selected by grouped cross-validation in the source data, without access to target ages. The assay-matched model achieved MAEs of 6.094 years in whole blood and 7.893 years in PBMCs; offset-only calibration yielded 7.088 and 4.020 years, respectively. The opposing cohort-specific effects indicate that missing-probe structure and mean calibration shift are insufficient to account for the observed transport error. Because this analysis was specified after the primary evaluation, it is interpreted as a diagnostic rather than confirmatory evidence.</p>':
        '<p>Refitting the source ridge model with probes represented in each target assay produced mean absolute errors of 6.094 years in whole blood and 7.893 years in peripheral blood mononuclear cells, whereas offset-only calibration produced errors of 7.088 and 4.020 years. These opposing cohort-specific responses indicate that neither unavailable probes nor a shift in mean calibration was sufficient to explain the observed transport error.</p>',
        '<p>Episodic neural adaptation reduced error relative to a prespecified support-selected comparator in two external cohorts, but its performance relative to fixed classical estimators depended on tissue and assay context. In particular, the unadapted source predictor remained strongest in whole blood, whereas neural adaptation was competitive with affine recalibration in PBMCs. These results separate adaptation performance from the reliability of model selection under limited supervision and argue for explicit reporting of both quantities.</p>':
        '<p>Episodic neural adaptation reduced prediction error relative to support-selected classical comparators in two external methylation cohorts, demonstrating that a representation learned in the source domain can improve model selection when target labels are scarce. The frozen source predictor nevertheless remained strongest in whole blood, while neural adaptation performed similarly to affine recalibration in peripheral blood mononuclear cells, showing that the value of adaptation depended on tissue composition and assay context.</p>',
        '<p>Future models should estimate the expected benefit of adaptation conditional on assay coverage, tissue composition and source–target divergence. Any model developed using the present external results would require evaluation in an additional untouched cohort, because GSE40279 and GSE37008 would then constitute development data. The current partitions, predictions and statistical contrasts are therefore retained as a fixed record of this evaluation cycle.</p>':
        '<p>Further development should model the expected benefit of adaptation as a function of assay coverage, tissue composition and molecular divergence between source and target cohorts, since these factors produced distinct responses to probe matching and calibration. Validation in additional cohorts will be required to determine whether the observed improvements extend beyond GSE40279 and GSE37008 and to define the settings in which limited target supervision provides a reproducible advantage.</p>',
        '<p>The combined estimator achieved MAE = 8.74 years, compared with 9.71 years for metadata alone and 9.15 years for microbial features alone. The primary reduction was 0.97 years (95% conditional interval, 0.66–1.28); the secondary reduction was 0.41 years (0.10–0.74). Both intervals excluded zero under this conditional bootstrap procedure.</p>':
        '<p>Joint modelling of microbial features and cohort metadata achieved a participant-weighted mean absolute error of 8.74 years, compared with 9.71 years for metadata alone and 9.15 years for microbial features alone. The reductions of 0.97 years relative to metadata and 0.41 years relative to microbial features had 95% conditional intervals of 0.66 to 1.28 years and 0.10 to 0.74 years, respectively.</p>',
        '<p>The prespecified contrast with selected clock calibration was 0.004 years (95% conditional interval, −0.061 to 0.070). Although a microbial correction was selected in 12 of 15 outer training partitions, it did not produce a measurable held-out improvement. Residual integration therefore preserved the predictive accuracy of the methylation component but did not establish independent microbial complementarity.</p>':
        '<p>Comparison with inner-selected clock calibration yielded a mean reduction of 0.004 years with a 95% conditional interval from -0.061 to 0.070 years, despite selection of a microbial correction in 12 of 15 outer training partitions. Residual integration consequently recovered the predictive accuracy lost through early concatenation, while providing no measurable evidence that genus-level microbial features improved prediction beyond methylation-score calibration.</p>',
        '<p>Blood methylation discovery data were obtained from <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE41037">GSE41037</a>. Of 720 deposited samples, 360 were retained after restricting to healthy controls aged at least 18 years with a positive source quality-control flag. External validation used 274 control women from <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE19711">GSE19711</a>. Both processed matrices contained 27,578 CpG identifiers. The external target was age at recruitment, which may differ from age at blood collection.</p>':
        '<p>Blood methylation data from <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE41037">GSE41037</a> supplied 360 discovery samples after restriction of 720 deposited specimens to healthy adults with a positive source quality-control flag, while 274 control women from <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE19711">GSE19711</a> formed the external validation cohort. Both processed matrices contained 27,578 CpG identifiers, and age at recruitment was used as the external outcome because the precise age at blood collection was unavailable.</p>',
        '<p>Equal weighting is a prespecified implementation choice. It was not optimized using the unpaired cohorts. The inference interface requires matched participant indices, documented specimen linkage, and the fitted feature schemas. Missing, duplicated, or discordant participant identifiers are rejected. Independent subjects are not matched by age or by row order. Separate blood-only and skin-only inference methods are available when only one modality is measured.</p>':
        '<p>The prediction-level integration model assigns equal weight to methylation and microbiome estimates for participants with verified specimen linkage, while preserving separate modality-specific inference when only one assay is available. The implementation requires concordant participant indices and fitted feature schemas and rejects missing, duplicated or discordant identifiers, thereby preventing construction of artificial pairs from age or row order.</p>',
        '<p>Training-age median baselines were evaluated for both modalities. A skin metadata-only ridge model used study, body site, and sex. A fixed random forest with minimum leaf size 3 was evaluated using random-sample, participant-held-out, and leave-one-study-out splits to assess the effects of sampling structure. Ten label-permutation runs per modality were compared with matched unshuffled models; skin permutation operated on participant-mean ages.</p>':
        '<p>Validation included training-age median baselines for both modalities and a skin metadata ridge model containing study, body site and sex, together with a fixed random forest evaluated under random-sample, participant-held-out and leave-one-study-out partitions. Ten matched label-permutation runs were performed for each modality, with skin labels permuted at the level of participant-mean age to preserve the repeated-sampling structure.</p>',
        '<p>Source-training medians imputed missing measurements. Age-correlation screening selected 1,024 eligible CpGs, followed by source-training standardization and clipping at ±8 standard deviations. Source ridge regularization was chosen from α ∈ {10, 100, 1000} by group-held-out source validation. Feature selection preceded this internal alpha comparison; its development scores are therefore not unbiased generalization estimates. The external query comparisons remain independent of that selection. Source-training neural episodes used group-out-of-fold clock predictions to construct residual targets. GSE19711 ages refer to recruitment rather than necessarily the exact blood-collection date.</p>':
        '<p>Missing measurements were imputed with source-training medians before age-correlation screening selected 1,024 CpGs, after which values were standardized within the source data and clipped at eight standard deviations. Group-held-out validation selected the source ridge regularization parameter from values of 10, 100 and 1,000, and group out-of-fold clock predictions supplied the residual targets used during episodic neural training. Feature selection preceded the internal regularization comparison, whereas all external query comparisons remained isolated from this source-domain development procedure.</p>',
        'Figure 2—clock-preserving model. (a) Matched-participant MAE for the original early fusion, OLS clock calibration, inner-selected clock calibration, and protected residual fusion. (b) Paired MAE reductions relative to early fusion and selected calibration. Conditional 95% participant-bootstrap intervals use losses averaged across three repetitions. The improvement over early fusion is a post hoc engineering comparison. The prespecified microbial-complementarity contrast versus calibration alone is approximately zero. All models use the same 123 participants and outer partitions; this is exploratory reuse of a previously analyzed cohort.':
        'Figure 2. Clock-preserving residual integration in the paired HI-SEED cohort. (a) Participant-level mean absolute error for early feature integration, ordinary least-squares clock calibration, inner-selected clock calibration and residual integration across three repeated outer partitions. (b) Paired reductions in mean absolute error relative to early integration and selected calibration, with 95% conditional participant-bootstrap intervals calculated from losses averaged across repetitions. Residual integration recovered the accuracy of clock calibration after the degradation produced by early feature integration, while the contrast with calibration alone was centred near zero.',
        'Figure 1—clock-preserving architecture. An unpenalized clock calibration is combined with kernel regression of the remaining age residuals on clock-orthogonalized microbial features. Inner validation selects calibration, kernel, regularization, correction strength, or clock-only fallback. Orthogonalization removes linear clock-associated microbial variation within training data; it does not establish biological independence.':
        'Figure 1. Clock-preserving residual architecture. An unpenalized calibration model estimates age from the methylation-clock score, after which a kernel regression model estimates the remaining age residual from microbial features orthogonalized with respect to the clock within each training partition. Inner validation selects the calibration estimator, kernel function, regularization parameter and correction magnitude.',
        'Figure 2—paired-cohort extension. Exploratory repeated nested validation in 123 HI-SEED participants with released Horvath clock scores and gut genus profiles. (a) MAE with conditional 95% participant-bootstrap intervals. (b) Calibrated-clock MAE minus combined-model MAE; negative values indicate worse performance with fusion. This experiment uses a pretrained clock score rather than raw methylation features; skin microbes and proteins are not measured in this comparison.':
        'Figure 2. Early multimodal integration in 123 HI-SEED participants with paired Horvath clock scores and gut microbial genus profiles. (a) Mean absolute error across three repeated nested validations with conditional 95% participant-bootstrap intervals. (b) Paired difference between calibrated-clock and integrated-model error, where negative values indicate higher error after integration.',
        '<p>Within each training partition, clock calibration was selected among ordinary least squares, Huber regression, and unpenalized median regression. Microbial Hellinger features were residualized against the clock using training-only multivariate linear regression. A linear or RBF kernel ridge model then predicted training age residuals after clock calibration. RBF γ was fixed at 1; α ∈ {0.1, 1, 10} and correction strength ∈ {0.25, 1} were compared with a no-correction fallback. Three-fold inner MAE selected configurations, nested within the same three five-fold participant partitions used previously. Model families and the primary contrast were <a href="/projects/age-prediction/results/protected_design.json">recorded before this experiment</a>. Because the cohort had already been analyzed, this remains exploratory model development. The bootstrap treats each participant’s repeated-prediction loss as fixed and does not incorporate retraining or prior adaptive research choices. Full results and conditional sign-flip sensitivity tests are included in the <a href="/projects/age-prediction/results/protected_summary.json">model summary</a>.</p>':
        '<p>Within each training partition, clock calibration was selected among ordinary least squares, Huber regression and unpenalized median regression, after which Hellinger-transformed microbial features were orthogonalized with respect to the clock by multivariate linear regression fitted exclusively to the training data. Linear and radial basis function kernel ridge models predicted residual age after clock calibration, with three-fold inner validation selecting the calibration model, kernel, regularization parameter and correction magnitude inside each of three five-fold participant partitions. Conditional intervals were obtained by resampling participant-level losses averaged across repetitions, and the complete model comparison is reported in the <a href="/projects/age-prediction/results/protected_summary.json">model summary</a>.</p>',
        '<p>Horvath scores were calibrated by linear regression in each training fold. Genus abundances underwent sample-local Hellinger transformation. Microbiome and concatenated clock–microbiome ridge models used training-fold standardization, with α ∈ {0.1, 1, 10, 100, 1000} selected by three-fold inner validation for MAE. Three seeded five-fold outer partitions kept participants separate. Clinical outcomes, age-acceleration residuals and the ambiguously scaled GrimAge2 column were excluded from prediction inputs. Conditional intervals resampled 123 participants 10,000 times after averaging each participant’s absolute losses across repeats. The <a href="/projects/age-prediction/results/hiseed_design.json">specification and source-code hash</a> were recorded before execution; <a href="/projects/age-prediction/results/hiseed_summary.json">all model summaries</a> are available.</p>':
        '<p>Within each training fold, Horvath scores were calibrated by linear regression and genus abundances were transformed by the sample-local Hellinger procedure before standardization of the microbiome and concatenated clock-microbiome feature matrices. Three-fold inner validation selected ridge regularization from values of 0.1, 1, 10, 100 and 1,000 within each of three seeded five-fold participant partitions, while clinical outcomes, age-acceleration residuals and the ambiguously scaled GrimAge2 column were excluded from the predictors. Conditional intervals were calculated from 10,000 resamples of participant-level losses averaged across repetitions.</p>',
        '<p>The model artifact contains both fitted regressors, their feature identifiers, and the fusion operator. Fitting was executed on Modal using four CPU cores; the selected estimators did not require GPU execution. Serialization checks confirmed preservation of predictions. The refitted blood model differed from the previously recorded external predictions by at most 0.00014 years, consistent with numerical differences between compute environments. No paired test participants were available, so the model manifest records joint accuracy as unestimated.</p>':
        '<p>The fitted model artifact contains both modality-specific regressors, their feature identifiers and the equal-weight fusion operator, with training performed on four Modal CPU cores and serialization verified by reproducing the recorded predictions. Refitting changed the external blood predictions by no more than 0.00014 years across compute environments, while evaluation of the joint output was deferred because verified paired blood and skin specimens were unavailable.</p>',
        '<p>MAE, root mean squared error, and R² were computed from held-out predictions. MAE intervals used 2,000 bootstrap resamples of assay plates for internal blood validation, samples for external blood validation, and participants for skin validation. These intervals condition on fitted predictions and do not include uncertainty from retraining. The random seed was 20260905. Comparisons across modalities are descriptive because the cohorts differ in demographic composition and age range.</p>':
        '<p>Mean absolute error, root mean squared error and R² were calculated from held-out predictions, with uncertainty estimated from 2,000 bootstrap resamples of assay plates for internal blood validation, samples for external blood validation and participants for skin validation. Analyses used random seed 20260905, and comparisons between modalities were interpreted with respect to the demographic composition and age range of their distinct source cohorts.</p>',
        '<p>The combined estimator comprised a metadata ridge model (α = 10) and a random forest fitted to its training residuals using microbial features. Their predictions were added at inference. One-hot encoding, prevalence filtering, residual construction, and all fitting were repeated inside each training partition. The forest used 160 trees and inner selection among minimum leaf sizes of 1, 3, and 8. The metadata comparator was selected by inner validation between ridge regression and a 160-tree metadata forest with minimum leaf size 10 and all metadata features available at each split. A separately tuned microbial forest provided the secondary comparator.</p>':
        '<p>The combined estimator added predictions from a metadata ridge model with a regularization parameter of 10 to predictions from a 160-tree random forest fitted to microbial residuals, with one-hot encoding, prevalence filtering and residual construction repeated within every training partition. Inner validation selected microbial forest leaf sizes of 1, 3 or 8 and compared the metadata ridge model with a metadata forest, while a separately tuned microbial forest provided the secondary comparator.</p>',
        '<p>GSE37008 reports normalized M-values, as documented in its <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSM908383">sample-table definition</a>. These were converted to beta values using β = 1/(1 + 2<sup>−M</sup>) before source scaling. An initial PBMC evaluation incorrectly used M-values directly and was invalidated during the final scale audit. The corrected evaluation retained every model weight, hyperparameter grid and support/query partition. The <a href="/projects/age-prediction/cycles/fewshot/results/scale_correction.json">correction record</a> and <a href="/projects/age-prediction/cycles/fewshot/results/input_units_audit.json">input-scale audit</a> document this replacement. Only corrected PBMC results appear here.</p>':
        '<p>Normalized M-values reported for GSE37008 were converted to beta values using β = 1/(1 + 2<sup>−M</sup>) before application of source-derived scaling, as required by the measurement definition in the <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSM908383">sample table</a>. Scale auditing identified and replaced an initial evaluation performed directly on M-values while retaining the model weights, hyperparameter grid and support and query partitions, and every reported peripheral blood mononuclear cell result derives from the corrected beta-value analysis.</p>',
        '<p>Each of six T4 GPU runs used 2,000 source-domain episodes and AdamW, with three seeds per augmentation condition. Episode support and query samples were disjoint. Augmentation applied task-level Gaussian shifts, multiplicative scales and feature masking to encoder inputs while keeping the supplied source-clock values fixed. Twelve fixed 16-shot episodes from the source-validation plate selected checkpoints every 100 training steps. Predictions were ensembled over the three seeds within each condition.</p>':
        '<p>Six T4 GPU runs each used 2,000 source-domain episodes optimized with AdamW, comprising three random seeds for each augmentation condition and disjoint support and query samples within every episode. Task-level Gaussian shifts, multiplicative scales and feature masking were applied to encoder inputs while source-clock values remained fixed, and twelve 16-shot episodes from the source-validation plate selected checkpoints at intervals of 100 training steps before predictions were ensembled across seeds.</p>',
    }
    for old, revised in replacements.items():
        fragment = fragment.replace(old, revised)

    # Apply the requested punctuation convention only to visible text nodes.
    parts = re.split(r'(<[^>]+>)', fragment)
    for i in range(0, len(parts), 2):
        entities = []
        def preserve_entity(match):
            entities.append(match.group(0))
            return f'__ENTITY_{len(entities) - 1}__'
        text = re.sub(r'&(?:#\d+|#x[0-9A-Fa-f]+|[A-Za-z][A-Za-z0-9]+);', preserve_entity, parts[i])
        text = text.replace('—', ', ').replace(';', ',').replace(':', ',')
        text = re.sub(r'\s+,', ',', text)
        for index, entity in enumerate(entities):
            text = text.replace(f'__ENTITY_{index}__', entity)
        parts[i] = text
    return ''.join(parts)
